WITH valid AS (SELECT *, CONCAT(firmware, ' ', device_code) AS firmware_device_code FROM device_readings WHERE pressure BETWEEN 1024 AND 1027), with_gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS is_new_session FROM valid), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM with_gaps) SELECT device_code, PERCENTILE_APPROX(temp_c, 0.9) AS temp_c_p90, MAX(reading_ts) AS last_reading_ts, COUNT(*) FILTER (WHERE device_code = 'DV-04') AS dv_04_rows, SUM(temp_c) AS total_temp_c FROM islands GROUP BY device_code ORDER BY dv_04_rows DESC;
